    :root {
      --ink: #08121c;
      --glass: rgba(5, 13, 22, .78);
      --line: rgba(185, 224, 238, .36);
      --gold: #f8b45e;
      --cyan: #63e0e8;
      --red: #ff4961;
    }
    * { box-sizing: border-box; }
    html, body { margin: 0; width: 100%; height: 100%; overflow: hidden; background: #111820; color: #eff4f3; font-family: Chakra, Arial, sans-serif; }
    #view { position: fixed; inset: 0; width: 100%; height: 100%; display: block; }
