    .damage-pop { position:absolute; color:#ffe176; font:900 24px Chakra,Arial,sans-serif; -webkit-text-stroke:2px #211921; paint-order:stroke; text-shadow:0 0 10px #ff7a3a,0 2px 2px #111; transform:rotate(-7deg); }
