    .brand { font: 30px Faster; letter-spacing: .02em; color: #f4eee0; }
    .brand i { color: var(--gold); font-style: normal; }
    .district { margin-top: 4px; color: #b6d5dd; font-size: 11px; letter-spacing: .25em; }
    .economy { min-width: 150px; padding: 10px 15px; border: 1px solid var(--line); background: var(--glass); backdrop-filter: blur(8px); text-align: right; }
