    .radar-column { position: relative; width: 184px; height: 214px; padding-top: 24px; }
    .radar-frame { position: relative; width: 184px; height: 184px; padding: 4px; border: 2px solid #c4d5d7; border-radius: 50%; background: #07131d; box-shadow: 0 0 0 2px #263b45, 0 0 20px #55e5ec35; overflow: hidden; }
    #radar { display: block; width: 100%; height: 100%; border-radius: 50%; opacity: 1; }
    .radar-label { position: absolute; left: 0; right: 0; top: 0; padding: 3px 7px; border: 1px solid #b8d7df55; border-radius: 6px; background: rgba(8, 16, 28, .82); color: #c8ebea; text-align: center; font-size: 8px; line-height: 1.15; }
    .radar-label b { display: block; color: #f2c36e; font-size: 9px; }
    .radar-north { position: absolute; z-index: 1; top: 18px; left: 50%; transform: translateX(-50%); padding: 1px 5px; border-radius: 8px; background: #e5f1ee; color: #12242b; font-size: 8px; font-weight: 700; }
    .vitals { width: 150px; padding: 8px 10px; border: 1px solid var(--line); background: var(--glass); backdrop-filter: blur(8px); }
    .vitals small { color: #b7c9ca; font-size: 9px; }
