    .weapon-line { color: #d9e7e4; font: italic 700 12px Chakra,sans-serif; }
    .weapon-line span { margin-left: 8px; color: #8ea9af; }
    .radio { position: absolute; left:50%; bottom:22px; transform:translateX(-50%); width:390px; padding:10px 15px 10px 61px; border:1px solid #d1e3df55; border-left:2px solid var(--gold); background:rgba(5,13,22,.82); color:#dbe8e2; font-size:11px; letter-spacing:.05em; line-height:1.35; backdrop-filter:blur(7px); }
    .radio::before { content:'MS'; position:absolute; left:13px; top:12px; width:34px; height:34px; display:grid; place-items:center; border:1px solid #e9bb7a; border-radius:50%; background:radial-gradient(circle at 36% 29%, #d4a882 0 19%, #233541 20% 49%, #0c1921 50%); color:#fff2d8; font-size:9px; font-weight:bold; box-shadow:0 0 15px #e7ad6255; }
    .dispatch { position:absolute; right:16px; top:155px; width:262px; padding:9px 12px; border:1px solid #d4e4e044; border-radius:8px; background:rgba(8,16,28,.72); font-size:9px; letter-spacing:.07em; backdrop-filter:blur(8px); }
    .dispatch strong { color:#efbd72; font-size:10px; }
    .dispatch div { display:flex; justify-content:space-between; margin-top:5px; color:#cadbd7; }
    .loadout { position:absolute; top:86px; right:26px; display:flex; gap:4px; }
    .loadout span { padding:6px 8px; border:1px solid #cddcd94b; background:#08141bcc; color:#bdcfca; font-size:8px; letter-spacing:.04em; }
    .loadout span.active { color:#ffe1a0; border-color:#edb762; box-shadow:0 0 12px #e9a74a44; }
