    .title-panel, .modal, .map-panel { position: relative; border: 1px solid rgba(214, 228, 221, .35); background: linear-gradient(112deg, rgba(6, 13, 20, .93), rgba(13, 24, 33, .78)); box-shadow: 0 25px 90px #02070bb5; backdrop-filter: blur(12px); clip-path: polygon(0 0, 98% 0, 100% 10%, 100% 100%, 2% 100%, 0 91%); }
    #panel-layer { position: fixed; inset: 0; display: grid; place-items: center; background: linear-gradient(90deg, rgba(5, 10, 16, .48), rgba(5, 10, 16, .12) 65%, rgba(5, 10, 16, .35)); }
