          const escape = pedestrian.position.clone().sub(threatPosition);
          escape.y = 0;
          if (escape.lengthSq() > 0.1) data.heading = Math.atan2(-escape.z, escape.x);
          data.flee = Math.min(6, data.flee + dt * 2.5);
